# PIPELINE QC SUMMARY
# ============================================================

qc_summary <- tibble::tibble(
  
  metric = c(
    
    "candidate_loci_TSS",
    
    "candidate_loci_operon",
    
    "candidate_loci_integrated",
    
    "method_level_interactions",
    
    "unique_prediction_loci",
    
    "interactions_CopraRNA",
    
    "interactions_IntaRNA",
    
    "interactions_TargetRNA2",
    
    "genes_operon_compatible_with_local_TSS",
    
    "genes_internal_or_last_with_local_TSS",
    
    "genes_without_representative_TSS",
    
    "defined_operon_aware_5UTRs",
    
    "candidate_internal_transcript_5UTRs",
    
    "interactions_classified_5UTR",
    
    "interactions_candidate_internal_5UTR",
    
    "interactions_overlapping_start_codon",
    
    "interactions_CDS",
    
    "interactions_upstream_of_TSS",
    
    "prediction_statistics_QC_rows",
    
    "duplicate_method_level_interactions"
  ),
  
  
  value = c(
    
    nrow(tss),
    
    nrow(operon),
    
    nrow(
      transcript_context_final
    ),
    
    nrow(
      interaction_context_final
    ),
    
    dplyr::n_distinct(
      interaction_context_final$
        reference_locus
    ),
    
    sum(
      interaction_context_final$
        method ==
        "CopraRNA",
      na.rm = TRUE
    ),
    
    sum(
      interaction_context_final$
        method ==
        "IntaRNA",
      na.rm = TRUE
    ),
    
    sum(
      interaction_context_final$
        method ==
        "TargetRNA2",
      na.rm = TRUE
    ),
    
    sum(
      transcript_context$
        operon_start_compatible &
        transcript_context$
        has_representative_TSS,
      na.rm = TRUE
    ),
    
    sum(
      !transcript_context$
        operon_start_compatible &
        transcript_context$
        has_representative_TSS,
      na.rm = TRUE
    ),
    
    sum(
      !transcript_context$
        has_representative_TSS,
      na.rm = TRUE
    ),
    
    sum(
      !is.na(
        transcript_context$
          operon_aware_UTR5_length
      )
    ),
    
    sum(
      transcript_context$
        UTR_interpretation ==
        "Candidate_internal_transcript_5UTR",
      na.rm = TRUE
    ),
    
    sum(
      interaction_context_final$
        binding_context ==
        "5UTR",
      na.rm = TRUE
    ),
    
    sum(
      interaction_context_final$
        binding_context ==
        "candidate_internal_5UTR",
      na.rm = TRUE
    ),
    
    sum(
      interaction_context_final$
        binding_context ==
        "overlaps_start_codon",
      na.rm = TRUE
    ),
    
    sum(
      interaction_context_final$
        binding_context ==
        "CDS",
      na.rm = TRUE
    ),
    
    sum(
      interaction_context_final$
        binding_upstream_of_selected_TSS,
      na.rm = TRUE
    ),
    
    nrow(
      prediction_statistics_qc
    ),
    
    nrow(
      duplicate_interactions
    )
  )
)



